pub unsafe fn callback_extras(id: i32, data: *const c_void, size: usize) -> Vec<Extra> {
    match id {
        4502 => {
            // pBGRA is unWide * unTall * 4 bytes of pixels, not a string.
            let w = read_u32(data, size, offset_of!(sys::HTML_NeedsPaint_t, unWide)) as usize;
            let h = read_u32(data, size, offset_of!(sys::HTML_NeedsPaint_t, unTall)) as usize;
            let p = read_ptr(data, size, offset_of!(sys::HTML_NeedsPaint_t, pBGRA));
            let len = w.saturating_mul(h).saturating_mul(4).min(256 * 1024 * 1024);
            let pixels = if p.is_null() { Vec::new() } else { std::slice::from_raw_parts(p as *const u8, len).to_vec() };
            vec![Extra::Bytes(pixels)]
        }
        4503 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_StartRequest_t, pchURL))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_StartRequest_t, pchTarget))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_StartRequest_t, pchPostData)))],
        4505 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_URLChanged_t, pchURL))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_URLChanged_t, pchPostData))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_URLChanged_t, pchPageTitle)))],
        4506 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_FinishedRequest_t, pchURL))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_FinishedRequest_t, pchPageTitle)))],
        4507 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_OpenLinkInNewTab_t, pchURL)))],
        4508 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_ChangedTitle_t, pchTitle)))],
        4513 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_LinkAtPosition_t, pchURL)))],
        4514 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_JSAlert_t, pchMessage)))],
        4515 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_JSConfirm_t, pchMessage)))],
        4516 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_FileOpenDialog_t, pchTitle))), extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_FileOpenDialog_t, pchInitialFile)))],
        4521 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_NewWindow_t, pchURL)))],
        4523 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_StatusText_t, pchMsg)))],
        4524 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_ShowToolTip_t, pchMsg)))],
        4525 => vec![extra_cstr(read_ptr(data, size, offset_of!(sys::HTML_UpdateToolTip_t, pchMsg)))],
        _ => Vec::new(),
    }
}

